textOptions.schema:
{
  "type": "object",
  "properties": {
    "funnel_step": {
      "type": "string",
      "enum": [
        "consentimento_optin",
        "coleta_faturamento",
        "coleta_valor",
        "verificacao_cnpj",
        "apresenta_ofertas",
        "geral"
      ],
      "description": "Etapa do funil identificada onde o cliente parou."
    },
    "message": {
      "type": "string",
      "description": "Texto exato e humanizado da mensagem para enviar no WhatsApp."
    },
    "buttons": {
      "type": ["array", "null"],
      "items": { "type": "string" },
      "description": "Array com 1 a 3 botões rápidos, ou null se não houver botões."
    }
  },
  "required": ["funnel_step", "message", "buttons"],
  "additionalProperties": false
}

parameters.jsCode:
const candidate = $('Listar Candidatos').item.json;
const aiRaw = $input.first()?.json || {};

// Compatibilidade total com n8n LangChain OpenAI v2.1
let rawData = aiRaw.output?.[0]?.content?.[0]?.text || aiRaw.text || aiRaw.message?.content || aiRaw.output || aiRaw;

let parsed = {
  funnel_step: "geral",
  message: "",
  buttons: null
};

try {
  if (typeof rawData === "string") {
    const start = rawData.indexOf('{');
    const end = rawData.lastIndexOf('}');
    if (start >= 0 && end >= 0) {
      parsed = JSON.parse(rawData.substring(start, end + 1));
    }
  } else if (typeof rawData === "object" && rawData !== null) {
    parsed = rawData;
  }
} catch (e) {}

const finalMessage = parsed.message || `Olá! Vi que paramos a simulação de crédito para a ${candidate.company_name}. Gostaria de continuar de onde paramos para conferir os valores liberados?`;
let buttonsObj = null;

if (Array.isArray(parsed.buttons) && parsed.buttons.length > 0) {
  buttonsObj = {
    tipo: "botoes",
    opcoes: parsed.buttons
  };
}

return [{
  json: {
    queue_id: candidate.queue_id,
    conversation_id: candidate.conversation_id,
    phone: candidate.phone,
    company_name: candidate.company_name,
    funnel_step: parsed.funnel_step || "geral",
    message: finalMessage,
    interactive_buttons: buttonsObj
  }
}];

const items = $input.all();
const list = items.map(item => item.json);

return [{
  json: {
    executed_at: new Date().toISOString(),
    total_processed: list.length,
    results: list,
    summary_log: `🚀 Sofia (IA) analisou ${list.length} conversas com precisão e enfileirou mensagens contextuais no WhatsApp!`
  }
}];

const inputData = $input.first()?.json || {};
return [{
  json: {
    executed_at: new Date().toISOString(),
    enqueued_count: 0,
    reason: inputData.reason || "Nenhum lead com tempo de inatividade expirado no momento.",
    status: "NO_ACTION_REQUIRED"
  }
}];
